#pragma once
#include <jsd/engine.hpp>
#include <fstream>
#include "process_id.hpp"
template<class Check>void minimalSettingsTests(Check check){using namespace rf::gfx;auto s=GraphicsSettings::minimal();check(s.viewDistance==320&&s.textureQuality==TextureQuality::Lowest&&s.renderScale==1,"minimal extends visibility fourfold with native output and lowest textures");check(textureEdgeLimit(TextureQuality::Lowest)==64&&textureEdgeLimit(TextureQuality::Low)==512&&int(TextureQuality::Ultra)==3,"lowest texture budget preserves existing quality IDs and limits");Capabilities c;c.maxTextureSize=256;auto r=resolveSettings(GraphicsSettings::high(),c);check(r.effective.textureQuality==TextureQuality::Lowest,"small texture capability selects actual lowest supported tier");std::string error;auto p=std::filesystem::temp_directory_path()/("jsd-minimal-settings-"+std::to_string(jsdTestProcessId()));check(saveSettings(p,s,error),"lowest texture settings save");auto restored=GraphicsSettings::high();check(loadSettings(p,restored,error)&&restored==s,"lowest texture settings roundtrip");std::filesystem::remove(p);}
template<class Check>void minimalGraphicsTests(Check check,rf::gfx::Renderer&r){using namespace rf;using namespace rf::gfx;auto initial=r.settings().requested;auto highBefore=initial;highBefore.textureQuality=TextureQuality::High;r.setSettings(highBefore);std::vector<unsigned char>ormPixels(4*4*4,255);for(unsigned n=0;n<16;n++){ormPixels[n*4+1]=180;ormPixels[n*4+2]=0;}auto orm=r.createTexture(4,4,ormPixels,false);auto s=GraphicsSettings::minimal();r.setSettings(s);std::vector<unsigned char>pixels(1024*512*4,160);auto tex=r.createTexture(1024,512,pixels);check(r.textureDimensions(tex)==std::pair{64,32},"lowest resizes real GPU textures to 64 px edge");auto frame=[&](bool terrain=false){r.begin({{0,3,0},{0,0,1},60,.08f});Material m;m.emissive={2,.2f,.05f,1};m.albedoTexture=tex;m.ormTexture=orm;m.metallic=1;r.primitive(Primitive::Box,{{0,3,250},{30,30,30},0},m);if(terrain){Terrain t;t.height=[](float x,float z){return std::sin(x*.02f)*std::cos(z*.02f);};r.terrain(t);}r.end();r.check();r.validateFrame();};frame();check(r.statistics().lightweightRendering&&r.statistics().sceneColorAttachments==1,"minimal uses compact forward rendering without deferred attachments");check(r.statistics().triangles>=12,"minimal renders distant object beyond old 80 m cutoff");auto minimalPasses=r.statistics().postPasses;s.ambientOcclusion=Quality::Low;r.setSettings(s);frame();check(!r.statistics().lightweightRendering&&r.statistics().sceneColorAttachments==4&&r.statistics().postPasses>minimalPasses,"enabling effects restores full buffers and rendering pipeline");auto fullDump=std::filesystem::temp_directory_path()/("jsd-minimal-orm-"+std::to_string(jsdTestProcessId()));r.captureBuffers(fullDump);auto material=jsd::loadImage(fullDump/"material.ppm");auto center=(size_t(material.height/2)*material.width+material.width/2)*4;check(material.rgba[center+1]==0&&material.rgba[center]>100,"lowest preserves averaged material parameters when switching from small full-quality ORM maps");std::filesystem::remove_all(fullDump);s=GraphicsSettings::minimal();r.setSettings(s);frame(true);check(r.statistics().lightweightRendering&&r.statistics().triangles<40000&&r.statistics().visibleTerrainTiles>0,"long distance minimal terrain stays within coarse geometry budget");auto p=std::filesystem::temp_directory_path()/("jsd-minimal-buffers-"+std::to_string(jsdTestProcessId()));r.captureBuffers(p);std::ifstream f(p/"pipeline.txt");std::string label;std::getline(f,label);check(label.find("lightweight forward")!=std::string::npos&&std::filesystem::exists(p/"normal.ppm"),"compact diagnostics explicitly label neutral deferred placeholders");r.check();std::filesystem::remove_all(p);r.begin({{0,3,0},{0,0,1},60,.08f});r.image(tex,0,0,100,100);r.end();r.check();r.validateFrame();check(r.textureDimensions(tex)==std::pair{1024,512},"screen images retain readable source detail on minimal");auto high=GraphicsSettings::high();r.setSettings(high);frame();check(!r.statistics().lightweightRendering&&r.statistics().sceneColorAttachments==4,"raising quality restores full graphics path and source images");r.destroyTexture(tex);r.destroyTexture(orm);r.setSettings(initial);}
